219	function syncProofHeadlines(progress: number): void {
220	  const h1 = document.querySelector<HTMLElement>(PROOF_H1_SELECTOR);
221	  const h2 = document.querySelector<HTMLElement>(PROOF_H2_SELECTOR);
222	  if (!h1 || !h2) return;
223	
224	  const a1 = _rangeAlpha(progress, 0, 0.15, 0.45, 0.6);
225	  const a2 = _rangeAlpha(progress, 0.45, 0.6, 1.1, 1.1);
226	
227	  h1.style.opacity = String(a1);
228	  h1.style.filter = `blur(${(1 - a1) * PROOF_BLUR_PX}px)`;
229	  h2.style.opacity = String(a2);
230	  h2.style.filter = `blur(${(1 - a2) * PROOF_BLUR_PX}px)`;
231	}
