233	function resetProofHeadlines(): void {
234	  const h1 = document.querySelector<HTMLElement>(PROOF_H1_SELECTOR);
235	  const h2 = document.querySelector<HTMLElement>(PROOF_H2_SELECTOR);
236	  if (h1) { h1.style.opacity = "0"; h1.style.filter = `blur(${PROOF_BLUR_PX}px)`; }
237	  if (h2) { h2.style.opacity = "0"; h2.style.filter = `blur(${PROOF_BLUR_PX}px)`; }
238	}
