248	function syncAboutContactHead(progress: number): void {
249	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
250	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
251	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
252	  if (!section || !head || !actions) return;
253	
254	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
255	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
256	
257	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
258	  aboutSceneDomState.isContactHeadVisible = shouldShow;
259	  aboutSceneDomState.contactHeadTimers = clearTimers(
260	    aboutSceneDomState.contactHeadTimers,
261	  );
262	
263	  if (shouldShow) {
264	    section.dataset.active = "true";
265	    head.dataset.active = "true";
266	    actions.dataset.active = "true";
267	    TextReveal.setVisibleOff(textItems);
268	    textItems.forEach((item, index) => {
269	      const timerId = window.setTimeout(() => {
270	        TextReveal.setVisibleOn(item);
271	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
272	      aboutSceneDomState.contactHeadTimers.push(timerId);
273	    });
274	    return;
275	  }
276	
277	  textItems.forEach((item) => {
278	    TextReveal.setVisibleOff(item);
279	  });
280	  section.dataset.active = "false";
281	  head.dataset.active = "false";
282	  actions.dataset.active = "false";
283	}
