288	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
289	  if (!section || !head || !actions) return;
290	
291	  aboutSceneDomState.isContactHeadVisible = false;
292	  aboutSceneDomState.contactHeadTimers = clearTimers(
293	    aboutSceneDomState.contactHeadTimers,
294	  );
295	  section.dataset.active = "false";
296	  head.dataset.active = "false";
297	  actions.dataset.active = "false";
298	
299	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
300	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
301	}
