6	export class EnvSetup {
7	  private static readPageTypeFrom(el: Element | null): string | undefined {
8	    if (!el || !(el instanceof HTMLElement)) return undefined;
9	    return el.dataset.page;
10	  }
11	
12	  static getPageType(root?: ParentNode | null): string {
13	    const container = EnvSetup._resolvePageContainer(root);
14	    return (
15	      EnvSetup.readPageTypeFrom(container) ??
16	      (root instanceof HTMLElement ? root.dataset.barbaNamespace : undefined) ??
17	      document.body?.dataset.page ??
18	      pageMain
19	    );
20	  }
21	
22	  static getQueryParam(key: string): string | null {
23	    if (typeof window === "undefined") return null;
24	    try {
25	      const params = new URLSearchParams(window.location.search);
26	      return params.get(key);
27	    } catch (error) {
28	      console.warn("[EnvSetup.getQueryParam] Failed to parse query params.", error);
29	      return null;
30	    }
31	  }
32	
33	  static hasQueryFlag(key: string, expectedValue: string): boolean {
34	    return EnvSetup.getQueryParam(key) === expectedValue;
35	  }
36	
37	  static checkWebGL(): boolean {
38	    try {
39	      const canvas = document.createElement("canvas");
40	      return !!(
41	        canvas.getContext("webgl") || canvas.getContext("experimental-webgl")
42	      );
43	    } catch (error) {
44	      return false;
45	    }
46	  }
47	
48	  static checkCanvas(canvasId: string, root?: ParentNode | null): boolean {
49	    if (root instanceof HTMLElement && root.id === canvasId) return true;
50	    if (root?.querySelector?.(`#${canvasId}`)) return true;
51	    if (root) return false;
52	    return document.getElementById(canvasId) != null;
53	  }
54	
55	  static shouldInit(options: EnvInitOptions): EnvCheckResult {
56	    const pageType = EnvSetup.getPageType(options.root);
57	    const allowed = options.allowedPageTypes;
58	    if (allowed && !allowed.has(pageType)) {
59	      return {
60	        shouldInit: false,
61	        pageType,
62	        reason: "page type is not allowed",
63	      };
64	    }
65	    if (!EnvSetup.checkWebGL()) {
66	      return {
67	        shouldInit: false,
68	        pageType,
69	        reason: "webgl is not available",
70	      };
71	    }
72	    if (!EnvSetup.checkCanvas(options.canvasId, options.root)) {
73	      return {
74	        shouldInit: false,
75	        pageType,
76	        reason: "canvas host was not found",
77	      };
78	    }
79	    return { shouldInit: true, pageType };
80	  }
81	
82	  private static _resolvePageContainer(root?: ParentNode | null): HTMLElement | null {
83	    if (root instanceof HTMLElement) {
84	      if (root.matches("main[data-page]")) {
85	        return root;
86	      }
87	      return root.querySelector<HTMLElement>("main[data-page]");
88	    }
89	    if (root) {
90	      return root.querySelector<HTMLElement>("main[data-page]");
91	    }
92	    return (
93	      document.querySelector<HTMLElement>("main[data-page]") ??
94	      document.getElementById("main")
95	    );
96	  }
