107	function loadTexture(
108	  loader: THREE.TextureLoader,
109	  url: string,
110	  renderer: THREE.WebGLRenderer,
111	): Promise<THREE.Texture | null> {
112	  return new Promise((resolve) => {
113	    loader.load(
114	      url,
115	      (texture) => {
116	        texture.minFilter = THREE.LinearMipmapLinearFilter;
117	        texture.magFilter = THREE.LinearFilter;
118	        texture.generateMipmaps = true;
119	        texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
120	        resolve(texture);
121	      },
122	      undefined,
123	      () => resolve(null),
124	    );
125	  });
126	}
