409	    const clock = this._clock!;
410	    const renderer = this._renderer!;
411	    const scene = this._scene!;
412	    const camera = this._camera!;
413	    const count = this._imageCount;
414	    if (count === 0) {
415	      renderer.render(scene, camera);
416	      this._rafId = requestAnimationFrame(this._tick);
417	      return;
418	    }
419	
420	    const delta = Math.min(clock.getDelta(), MAX_DELTA);
