596	  private _detachContextEvents(): void {
597	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
598	    const canvas = this._renderer.domElement;
599	    if (this._onContextLost) {
600	      canvas.removeEventListener("webglcontextlost", this._onContextLost);
601	    }
602	    if (this._onContextRestored) {
603	      canvas.removeEventListener(
604	        "webglcontextrestored",
605	        this._onContextRestored,
606	      );
607	    }
608	    this._onContextLost = null;
609	    this._onContextRestored = null;
610	    this._contextLost = false;
611	  }
