655	  private _shouldSkipPostProcessing(frameExceeded: boolean): boolean {
656	    if (!this._postProcessor || this._renderBudget.mode !== "performance") {
657	      this._resetRenderModeState();
658	      return false;
659	    }
660	
661	    if (frameExceeded) {
662	      this._renderModeState.exceededFrames += 1;
663	      this._renderModeState.stableFrames = 0;
664	      if (
665	        !this._renderModeState.skipActive &&
666	        this._renderModeState.exceededFrames >=
667	          this._renderBudget.enterSkipFrames
668	      ) {
669	        this._renderModeState.skipActive = true;
670	      }
671	      return this._renderModeState.skipActive;
672	    }
673	
674	    this._renderModeState.stableFrames += 1;
675	    this._renderModeState.exceededFrames = 0;
676	    if (
677	      this._renderModeState.skipActive &&
678	      this._renderModeState.stableFrames >= this._renderBudget.exitSkipFrames
679	    ) {
680	      this._renderModeState.skipActive = false;
681	    }
682	    return this._renderModeState.skipActive;
683	  }
